  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "明确特化的动机、函数及可变状态、请求描述、变体身份和合法域；二维分桶各长度以 token 为单位，执行复用边界与旧提交长度分开定义。局部符号复用有明确作用域，不影响算法解释。",
      "evidence": [
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "输出既包括 `y`，也包括状态变化 `z→z'`；输出张量接近而 KV 写错位置，仍然是不正确的执行。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "`a` 只是执行复用边界，不把旧提交长度降到 `a`。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "区分 guard 必要条件、程序正确性与后端策略；形状分支保留排除条件，padding 保留逻辑长度及可见集合。NxD 最小后缀桶策略、零前缀桶与容量失败符合所供原文；较大桶搜索和事务提交明确属于独立设计推导。TVM、Ansor 与 PyTorch 的版本事实未外推为当前性能保证。",
      "evidence": [
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "guard 通过只是允许执行的必要条件，不能弥补错误的 lowering、mask 或状态绑定。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "保留全部前缀、只补后缀 padding 也可能是另一种合法策略；它不符合上述优先迁移的选择规则，却不天然违反 attention 数学。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "提交描述符的原子发布是服务执行器的一种实现选择，不声称 NxD 文档提供了这个事务 API。"
        }
      ]
    },
    "algorithm": {
      "assessment": "sufficient",
      "reason": "PrefixBucket、RecomputeSuffixAndCommit 和 ResolveAndExecute 已贯通规划、执行和发布。第一层从已知 token 开始；各层读取对应层历史 KV、产生私有新增 KV、按 causal 集合计算并传递本轮隐藏状态，最终层末行生成 logits。公共描述符在完整成功前保持旧值，失败候选须排空后回收，重试仅读旧提交。完整命中缺 logits、空 prompt、空批及产物持续引用均有明确处理。K-FW-004-r2-layer-state-commit 已修复，campaign-K-FW-004-r2 所要求的完整候选复核完成。",
      "evidence": [
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "其历史来源只能是旧提交快照的同一层 `KV_old[ℓ,0:a)`。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "后继层消费的是这次重算得到的 `Xℓ`，不是重新使用 token embedding，也不是从第 `ℓ` 层缓存取出隐藏状态。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "最终只在第 `L` 层完成后，对有效末行 `Xᴸ[q−1]` 应用模型的 final norm 和 LM head，得到位置 `n−1` 的 logits，用于预测下一个 token。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "私有写区标为不可复用，直到全部在途访问排空后回收"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "六类成本均接到具体执行条件。线性工作和 attention 配对数区分迁移重算与 padding，避免重复计费；配对 FLOPs、KV 字节、gather 读写、候选 KV 驻留及准备摊销单位一致。900/640 算例及 10% 命中回本数正确。通信、同步和并存峰值按实际依赖及物理并集解释，未把逻辑流量或累计耗时当成设备事务或响应时间。",
      "evidence": [
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "因此可以拆成 `A_bucket−A_original=(A_valid−A_original)+(A_bucket−A_valid)`，分别解释重算与物理容量工作。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "若各层新增区都保留到统一提交，仅有效行的候选主项为 `q v_KV`；按整桶分配时可能是 `P v_KV`。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "时间应沿实际依赖取关键路径，并合并竞争同一带宽或执行资源的需求，不能把所有独占时间直接相加，也不能只看 kernel 时间。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "根据形状分布、部署寿命、前缀命中、布局、权重、图绑定、并行配置和内存压力说明保留的不变量及需要重选的策略，并列出对应决策证据。对动态输出、不同依赖结构及缺少可恢复状态合同的情况允许缩减或放弃专门路径。",
      "evidence": [
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "若高度动态的输出数量没有可接受上界、外部状态无法进入受支持表示，或成熟库已使可节省部分很小，应允许放弃整段专门编译。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "模型引入双向依赖、窗口或异构状态层组后，应重新定义各层可复用状态和可见集合，不能仅保留本章的普通全历史 causal mask。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "诊断表给出竞争解释、可控干预、不同预测和反证后的修改。检查包含独立 token 顺序参考、绝对位置 attention 参考、独立整段多层参考及实际执行的错误路径。后层失败诊断同时关注描述符和旧页内容，避免用逻辑非提交代替物理隔离。实际 preflight 与作者 JavaScript 复算、待执行 Python 的历史陈述已区分。",
      "evidence": [
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "正确性参考应独立于被测布局与 mask 生成器。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "除了 logits，还比较迁移区间的各层 K/V；最终输出碰巧接近不保证未来 decode 读到正确缓存。"
        },
        {
          "path": "knowledge/frameworks/compile-dynamic-shapes.md",
          "quote": "失败检查同时比较提交描述符和旧状态内容：公共长度没有推进，却已经原地改坏旧页，也违反保留旧提交的要求。"
        }
      ]
    }
  },
  "findings": [],
  "limitations": [
    "结论限定于所供固定资料及普通 causal decoder 合同；S-TRITON 仅有作者核验后的机制说明，未独立阅读其上游实现。四份来源原文按完整提取文本阅读，未核对 PDF 图版或源码归档。",
    "三层检查采用标量投影、identity normalization 和 binary64 softmax，不验证真实 checkpoint、RoPE、FP16/FP8、量化 scale 或实际编译 lowering。",
    "提交检查使用不可变 CPU 元组和顺序事件；它验证整次发布及失败后重试的逻辑合同，不证明可变共享页/COW、scatter 地址、设备完成可见性、取消竞争、异步排空或多 rank 原子发布。",
    "没有 GPU/Neuron、真实编译器、服务性能或 Agent 使用效果证据。成本公式属于条件化模型和设定计算，不能作为目标设备收益或峰值实测。",
    "本次审阅未另行运行脚本；执行结论来自用户提供且绑定当前脚本哈希的 remote_bwrap preflight 记录。"
  ],
